// Everything the UI knows about DEX comes from /api/schema (generated by the
// hub from the DEX headers). These helpers interpret it generically.
import { state, update, live, pushSamples } from './store.js';
import { api } from './api.js';

export const typeInfo = (type) => state.schema?.types.find((t) => t.type === type);
export const enumDef = (name) => state.schema?.enums[name];
export const enumLabel = (name, value) => enumDef(name)?.values.find((v) => v.value === value)?.name ?? String(value);
export const deviceName = (key) => state.devices[key]?.name || key;
export const commandDef = (name) => state.schema?.commands.find((c) => c.name === name);
export const peripheralLabel = (p) => `${p.typeName || 'Unknown'} #${p.id}`;

// ---- Signal catalog ---------------------------------------------------------------
let rawSignals = [];
let pending = null;
export function refreshSignals() {
  if (pending) return pending;
  pending = new Promise((resolve) => setTimeout(resolve, 400))
    .then(() => api('/signals'))
    .then((list) => {
      rawSignals = list;
      // Seed live buffers with the latest stored value.
      for (const s of list) if (s.ts != null && !live.has(s.id)) pushSamples(s.ts, { [s.id]: s.value });
      rebuildSignals();
    })
    .catch(() => {})
    .finally(() => (pending = null));
  return pending;
}

export function rebuildSignals() {
  const signals = rawSignals.map((s) => {
    const type = typeInfo(s.type);
    const meta = type?.signals?.find((m) => m.key === s.key) ?? { label: s.key, kind: 'number' };
    const device = deviceName(s.device);
    const typeName = type?.name ?? `Type ${s.type}`;
    return {
      ...meta, id: s.id, key: s.key, device: s.device, peripheral: s.peripheral, type: s.type,
      deviceName: device, typeName, source: `${device} · ${typeName} #${s.peripheral}`,
      fullLabel: `${device} · ${typeName} #${s.peripheral} · ${meta.label}`,
    };
  });
  update({ signals, signalsById: new Map(signals.map((s) => [s.id, s])) });
}

export const signalsOf = (device, peripheral) =>
  state.signals.filter((s) => s.device === device && (peripheral == null || s.peripheral === peripheral));

// ---- Formatting -----------------------------------------------------------------------
const BYTES = ['B', 'KiB', 'MiB', 'GiB'];
export function formatNumber(value, unit = '', scaled = false) {
  if (value == null || Number.isNaN(value)) return { text: '—', unit: '' };
  if (unit === 'B') {
    let v = value, i = 0;
    while (Math.abs(v) >= 1024 && i < BYTES.length - 1) { v /= 1024; i++; }
    return { text: v.toLocaleString(undefined, { maximumFractionDigits: i ? 2 : 0 }), unit: BYTES[i] };
  }
  if (unit === 's' && value > 1e9) return { text: new Date(value * 1000).toLocaleString(), unit: '' };
  const abs = Math.abs(value);
  const digits = Number.isInteger(value) && !scaled ? 0 : abs >= 1000 ? 1 : abs >= 100 ? 1 : abs >= 10 ? 2 : 3;
  return { text: value.toLocaleString(undefined, { maximumFractionDigits: digits }), unit };
}

export const formatPlain = (value, unit) => {
  const f = formatNumber(value, unit, true);
  return f.unit ? `${f.text} ${f.unit}` : f.text;
};

export function formatSignal(signal, value) {
  if (value == null) return '—';
  if (signal.kind === 'enum') return enumLabel(signal.enum, value);
  if (signal.kind === 'bool') return value ? 'On' : 'Off';
  return formatPlain(value, signal.unit);
}

// ---- Semantics for color (generic, by enum/value names) --------------------------------
const STATE_TONES = {
  Running: 'ok', Ready: 'ok', Initializing: 'info', Busy: 'info', Waiting: 'info', Paused: 'neutral',
  Sleeping: 'neutral', Suspended: 'neutral', Stopping: 'warn', Stopped: 'neutral', Degraded: 'warn',
  Warning: 'warn', Fault: 'err', Disabled: 'neutral', Offline: 'err',
};
export function toneOf(enumName, value) {
  const name = String(value);
  if (enumName === 'Error') return 'err';
  if (enumName === 'Notification') return 'notif';
  if (enumName === 'State') return STATE_TONES[name] || 'neutral';
  if (/error|fail|invalid|abort|fault/i.test(name)) return 'err';
  if (/warn|pending|unknown|open/i.test(name)) return 'warn';
  if (/^(valid|ready|running|closed|idle|ok|on|new)$/i.test(name)) return 'ok';
  return 'accent';
}

export const SEVERITY = {
  notification: { tone: 'notif', icon: 'bell', label: 'Notification' },
  error: { tone: 'err', icon: 'alert', label: 'Error' },
  warning: { tone: 'warn', icon: 'alert', label: 'Warning' },
  success: { tone: 'ok', icon: 'check', label: 'Success' },
  info: { tone: 'info', icon: 'info', label: 'Info' },
};

const PALETTE = ['#7c8cff', '#22d3ee', '#f59e0b', '#22c55e', '#f43f5e', '#d946ef', '#a3e635', '#fb923c',
  '#38bdf8', '#e879f9', '#facc15', '#2dd4bf'];
export const colorFor = (id) => PALETTE[(id * 7 + 3) % PALETTE.length];

export function ago(ms) {
  if (!ms) return 'never';
  const s = Math.max(0, (Date.now() - ms) / 1000);
  if (s < 5) return 'just now';
  if (s < 60) return `${Math.floor(s)}s ago`;
  if (s < 3600) return `${Math.floor(s / 60)}m ago`;
  if (s < 86400) return `${Math.floor(s / 3600)}h ago`;
  return new Date(ms).toLocaleDateString();
}
